using ParallelGpu;

namespace MonteCarloPi;

/// <summary>Estimates pi by generating random points and reducing quarter-circle hits on the GPU.</summary>
public sealed class PiEstimator
{
    /// <summary>The borrowed GPU executor used for sampling and reduction.</summary>
    private readonly Gpu gpu;

    /// <summary>Gets the total number of random points to generate.</summary>
    public long SampleCount { get; }

    /// <summary>Gets the seed used to reproduce the same random points.</summary>
    public ulong Seed { get; }

    /// <summary>Gets the maximum number of points generated by each device iteration.</summary>
    public int SamplesPerIteration { get; }

    /// <summary>Gets the number of partial hit counts stored on the GPU.</summary>
    public int IterationCount { get; }

    /// <summary>Creates a GPU estimator with an explicit sample count, seed, and iteration size.</summary>
    /// <param name="gpu">The GPU executor to reuse; the caller retains ownership and disposes it.</param>
    /// <param name="sampleCount">The positive number of random points.</param>
    /// <param name="seed">The seed controlling the deterministic random sequence.</param>
    /// <param name="samplesPerIteration">The positive maximum number of samples processed per device iteration.</param>
    /// <exception cref="ArgumentNullException">The executor is null.</exception>
    /// <exception cref="ArgumentException">The executor uses a CPU accelerator.</exception>
    /// <exception cref="ArgumentOutOfRangeException">A count is not positive or the number of iterations exceeds Int32.MaxValue.</exception>
    public PiEstimator(Gpu gpu, long sampleCount, ulong seed, int samplesPerIteration = 256)
    {
        ArgumentNullException.ThrowIfNull(gpu);
        if (!gpu.IsGpu)
            throw new ArgumentException("MonteCarloPi requires a GPU accelerator.", nameof(gpu));
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(sampleCount);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(samplesPerIteration);

        long iterations = (sampleCount - 1) / samplesPerIteration + 1;
        if (iterations > int.MaxValue)
            throw new ArgumentOutOfRangeException(nameof(sampleCount),
                "Too many device iterations; reduce SampleCount or increase SamplesPerIteration.");

        this.gpu = gpu;
        SampleCount = sampleCount;
        Seed = seed;
        SamplesPerIteration = samplesPerIteration;
        IterationCount = (int)iterations;
    }

    /// <summary>Compiles the sampling and reduction kernels using a small portion of the configured points.</summary>
    /// <remarks>The random sequence has no mutable state, so warm-up does not affect the estimate.</remarks>
    public void WarmUp()
    {
        int iterations = Math.Min(IterationCount, 256);
        long samples = Math.Min(SampleCount, (long)iterations * SamplesPerIteration);
        CountHits(iterations, samples);
    }

    /// <summary>Generates the configured points, counts hits on the GPU, and computes the scalar pi estimate.</summary>
    /// <returns>The sample count, quarter-circle hit count, and resulting estimate.</returns>
    public PiEstimate Estimate()
    {
        long hits = CountHits(IterationCount, SampleCount);
        return new(SampleCount, hits, 4.0 * hits / SampleCount);
    }

    /// <summary>Stores one partial count per iteration and reduces those counts without downloading the buffer.</summary>
    /// <param name="iterations">The number of partial counts to allocate on the device.</param>
    /// <param name="samples">The number of points represented by this buffer.</param>
    /// <returns>The exact integer number of quarter-circle hits, downloaded as a single scalar.</returns>
    private long CountHits(int iterations, long samples)
    {
        using var partialHits = gpu.Allocate<long>(iterations);
        gpu.ForEach(partialHits, new HitCountKernel(samples, Seed, SamplesPerIteration));
        return gpu.Reduce(partialHits, new Int64Sum());
    }
}

/// <summary>Generates independent random points and writes a partial hit count per device iteration.</summary>
public readonly struct HitCountKernel : IGpuForEachKernel<long>
{
    /// <summary>The total number of points, including the final incomplete iteration.</summary>
    private readonly long sampleCount;

    /// <summary>The seed shared by all points in this run.</summary>
    private readonly ulong seed;

    /// <summary>The maximum number of points assigned to one iteration.</summary>
    private readonly int samplesPerIteration;

    /// <summary>Creates the device-compatible sampling state from validated estimator settings.</summary>
    /// <param name="sampleCount">The positive number of points.</param>
    /// <param name="seed">The deterministic random seed.</param>
    /// <param name="samplesPerIteration">The positive maximum number of points per iteration.</param>
    public HitCountKernel(long sampleCount, ulong seed, int samplesPerIteration)
    {
        this.sampleCount = sampleCount;
        this.seed = seed;
        this.samplesPerIteration = samplesPerIteration;
    }

    /// <summary>Generates this iteration's points and replaces its partial count.</summary>
    /// <param name="index">The zero-based device iteration index.</param>
    /// <param name="value">The device-resident partial hit count to write.</param>
    public void Execute(int index, ref long value)
    {
        long firstSample = (long)index * samplesPerIteration;
        long remaining = sampleCount - firstSample;
        int count = remaining < samplesPerIteration ? (int)remaining : samplesPerIteration;
        int hits = 0;
        for (int i = 0; i < count; i++)
        {
            // Global sample indices keep the random points identical when the iteration size changes.
            if (RandomPoints.IsInsideQuarterCircle(seed, (ulong)(firstSample + i)))
                hits++;
        }
        value = hits;
    }
}

/// <summary>Contains the exact GPU hit count and the approximate value of pi.</summary>
/// <param name="SampleCount">The number of generated random points.</param>
/// <param name="InsideCircle">The number of points inside the unit quarter-circle.</param>
/// <param name="Value">The estimate calculated as four times the hit fraction.</param>
public readonly record struct PiEstimate(long SampleCount, long InsideCircle, double Value);
